      ],
      "pattern": "drift",
      "direction": "increase",
      "magnitude": "~+0.07 to +0.08 A/E/year; A/E rises from 0.626 in 2015 to 1.307 in 2024; 2015-2019 combined AE~0.69 vs 2021-2024 combined AE~1.20",
      "confidence": 0.95,
      "evidence": [
        "artifacts/ae_death_by_year.csv: AE=0.626 in 2015, 0.784 in 2019, 0.983 in 2020, 1.063/1.113/1.261/1.307 in 2021-2024",
        "artifacts/ae_death_by_year.csv row blocks: 2015-2019 actual=1,175 vs expected=1,704 (AE=0.69); 2021-2024 actual=3,345 vs expected=2,789 (AE=1.20)",
        "summary.json Death overall AE=1.004 despite this strong opposite-sign early/late behavior; CI/TPD/IP by-year AE remain within sampling noise"
      ],
      "recommended_action": "Investigate Death experience and data quality. First check extract completeness, reporting lag/claim development, exposure scaling, and expected-claim model changes around 2020. Then review age/gender/cause mix and compare with benchmarks. If the experience shift is real, split pricing/valuation experience into pre- and post-2020 periods, revise mortality trend assumptions, and assess impact on pricing and reserves."
    }
  ]
}

